// Motor de reglas mínimo (patrón del gateway: reglas primero, IA como fallback).
// Entrada simplificada del trigger: { mensaje, sessionId, esPrimerTurno, hayAgenteHumano, contacto, inputs, ... }
const e = $input.first().json;
const texto = String(e.mensaje || '').toLowerCase();
const has = (palabras) => palabras.some((p) => texto.includes(p));

const TYPES = ['sendText','sendImage','sendFile','addTag','userDelegate','teamDelegate','addVar','setVar','input','updateContact'];
let actions = [];

if (e.esPrimerTurno) {
	actions = [
		{ type: 'sendText', text: `¡Hola${e.contacto?.nombre ? ' ' + e.contacto.nombre : ''}! Soy el asistente virtual. ¿En qué puedo ayudarte?` },
	];
} else if (has(['humano', 'asesor', 'persona', 'agente'])) {
	actions = [
		{ type: 'sendText', text: 'Con gusto, te transfiero con nuestro equipo.' },
		{ type: 'teamDelegate', id_team: 0 }, // ← ID de tu equipo (Group · Get Many)
	];
} else if (has(['precio', 'costo', 'cotiza', 'comprar', 'plan'])) {
	actions = [
		{ type: 'sendText', text: 'Claro, te ayudo con precios. ¿Qué producto o plan te interesa?' },
		{ type: 'addVar', varname: 'intencion', varvalue: 'precio' },
	];
} else {
	// Fallback (aquí puedes enchufar la salida de un AI Agent)
	actions = [{ type: 'sendText', text: 'Cuéntame un poco más para poder ayudarte.' }];
}

// Saneo: solo tipos válidos, nunca vacío.
actions = actions.filter((a) => a && TYPES.includes(a.type));
if (actions.length === 0) {
	actions = [{ type: 'sendText', text: 'No pude procesar tu solicitud, dame más detalles.' }];
}

// CRÍTICO: input de cierre salvo delegación (sin input, LiveConnect sale del callback).
const delega = actions.some((a) => a.type === 'userDelegate' || a.type === 'teamDelegate');
if (!delega && !actions.some((a) => a.type === 'input')) {
	actions.push({ type: 'input', input: '' });
}

// Envelope apiResp obligatorio: actions SIEMPRE bajo data.
return [{ json: { status: 1, status_message: 'Ok', data: { actions } } }];
